//! Small pieces of C++ runtime behavior the original program relies on.
//!
//! The C++ `main` converts the port with `std::stoi` and never catches what it
//! throws, so a bad port aborts the process instead of printing anything. Both
//! the parsing rules and that failure mode are reproduced here.

use std::process;

/// `std::stoi` accepts values up to `INT_MAX`, and down to `INT_MIN` when
/// negated. Digits are accumulated until the magnitude passes this bound, past
/// which the exact value no longer matters -- only that it is out of range.
const MAGNITUDE_LIMIT: i64 = -(i32::MIN as i64);

/// Converts a decimal string the way `std::stoi(text)` does: skip leading
/// whitespace, take an optional sign, then consume digits and ignore whatever
/// trailing text follows.
///
/// Aborts the process, as the uncaught C++ exception would, when there are no
/// digits to read or the value does not fit in an `i32`.
pub fn stoi(text: &str) -> i32 {
    let bytes = text.as_bytes();
    let mut at = 0;

    while at < bytes.len() && is_c_space(bytes[at]) {
        at += 1;
    }

    let negative = match bytes.get(at) {
        Some(b'-') => {
            at += 1;
            true
        }
        Some(b'+') => {
            at += 1;
            false
        }
        _ => false,
    };

    let first_digit = at;
    let mut magnitude: i64 = 0;
    let mut too_large = false;
    while let Some(&byte) = bytes.get(at) {
        if !byte.is_ascii_digit() {
            break;
        }
        if !too_large {
            magnitude = magnitude * 10 + i64::from(byte - b'0');
            too_large = magnitude > MAGNITUDE_LIMIT;
        }
        at += 1;
    }

    if at == first_digit {
        terminate("std::invalid_argument", "stoi");
    }

    let value = if negative { -magnitude } else { magnitude };
    if too_large || value < i32::MIN as i64 || value > i32::MAX as i64 {
        terminate("std::out_of_range", "stoi");
    }
    value as i32
}

/// The `isspace` set of the "C" locale, which includes the vertical tab that
/// `u8::is_ascii_whitespace` leaves out.
fn is_c_space(byte: u8) -> bool {
    matches!(byte, b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r')
}

/// Reproduces libstdc++'s report for an uncaught exception, then aborts so the
/// process dies on `SIGABRT` exactly as the C++ binary does.
fn terminate(exception: &str, what: &str) -> ! {
    eprintln!("terminate called after throwing an instance of '{exception}'");
    eprintln!("  what():  {what}");
    process::abort()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parses_plain_decimals() {
        assert_eq!(stoi("80"), 80);
        assert_eq!(stoi("0"), 0);
        assert_eq!(stoi("007"), 7);
        assert_eq!(stoi("65535"), 65535);
    }

    #[test]
    fn honors_signs_and_surrounding_whitespace() {
        assert_eq!(stoi("-1"), -1);
        assert_eq!(stoi("+80"), 80);
        assert_eq!(stoi("  80"), 80);
        assert_eq!(stoi("\t\n\u{b}\u{c}\r80"), 80);
        assert_eq!(stoi("  -0  "), 0);
    }

    #[test]
    fn stops_at_the_first_non_digit() {
        assert_eq!(stoi("80abc"), 80);
        assert_eq!(stoi("0x10"), 0);
        assert_eq!(stoi("1 2"), 1);
    }

    #[test]
    fn accepts_the_full_i32_range() {
        assert_eq!(stoi("2147483647"), i32::MAX);
        assert_eq!(stoi("-2147483648"), i32::MIN);
    }
