//! The `URL` value type, mirroring `url_parser::URL` from the C++ header.

use std::fmt;

/// Sentinel the C++ implementation stores when no usable port was supplied.
pub const NO_PORT: i32 = -1;

/// Highest port the C++ implementation keeps as-is; anything outside
/// `0..=MAX_PORT` collapses to [`NO_PORT`].
pub const MAX_PORT: i32 = 65535;

/// An absolute URL held as already-normalized components.
///
/// Normalization happens once, in [`URL::from_components`], so the accessors
/// and [`Display`](fmt::Display) always agree with each other.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct URL {
    scheme: String,
    host: String,
    port: i32,
    path: String,
    query: String,
    fragment: String,
}

impl URL {
    /// Builds a URL from its parts, normalizing scheme, port, and path.
    pub fn from_components(
        scheme: &str,
        host: &str,
        port: i32,
        path: &str,
        query: &str,
        fragment: &str,
    ) -> URL {
        URL {
            // Schemes are case-insensitive, so they fold to lower case. Only
            // ASCII folds: any other byte is passed through untouched, which is
            // what the C++ side does with a "C"-locale `tolower` per char.
            scheme: scheme.to_ascii_lowercase(),
            host: host.to_owned(),
            port: normalize_port(port),
            path: normalize_path(path),
            query: query.to_owned(),
            fragment: fragment.to_owned(),
        }
    }

    pub fn scheme(&self) -> &str {
        &self.scheme
    }

    pub fn host(&self) -> &str {
        &self.host
    }

    pub fn port(&self) -> i32 {
        self.port
    }

    pub fn path(&self) -> &str {
        &self.path
    }

    pub fn query(&self) -> &str {
        &self.query
    }

    pub fn fragment(&self) -> &str {
        &self.fragment
    }

    /// A URL counts as valid once it names something to address: either an
    /// authority or a path. Scheme, query, and fragment alone do not qualify.
    pub fn is_valid(&self) -> bool {
        !self.host.is_empty() || !self.path.is_empty()
    }
}

/// Keeps ports within `0..=MAX_PORT`, mapping everything else to [`NO_PORT`].
fn normalize_port(port: i32) -> i32 {
    if (0..=MAX_PORT).contains(&port) {
        port
    } else {
        NO_PORT
    }
}

/// Gives a non-empty path its leading slash. An empty path stays empty so that
/// it can be omitted from the rendered URL entirely.
fn normalize_path(path: &str) -> String {
    if path.is_empty() || path.starts_with('/') {
        path.to_owned()
    } else {
        format!("/{path}")
    }
}

/// Renders the URL; this is the `to_string()` of the C++ interface.
///
/// The authority is tied to the scheme: without a scheme there is no `//` to
/// introduce a host, so host and port are dropped and only the path, query,
/// and fragment remain.
impl fmt::Display for URL {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        if !self.scheme.is_empty() {
            write!(f, "{}://{}", self.scheme, self.host)?;
            if self.port != NO_PORT {
                write!(f, ":{}", self.port)?;
            }
        }
        f.write_str(&self.path)?;
        if !self.query.is_empty() {
            write!(f, "?{}", self.query)?;
        }
        if !self.fragment.is_empty() {
            write!(f, "#{}", self.fragment)?;
        }
        Ok(())
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn url(scheme: &str, host: &str, port: i32, path: &str) -> URL {
        URL::from_components(scheme, host, port, path, "", "")
    }

    #[test]
    fn renders_all_components() {
        let u = URL::from_components("https", "www.google.com", 443, "/search", "q=test", "results");
        assert_eq!(u.to_string(), "https://www.google.com:443/search?q=test#results");
        assert!(u.is_valid());
    }

    #[test]
    fn lowercases_only_the_ascii_of_the_scheme() {
        assert_eq!(url("HtTpS", "H.com", 1, "/").scheme(), "https");
        // Host case is significant and preserved.
        assert_eq!(url("HTTP", "EXAMPLE.COM", 80, "/").host(), "EXAMPLE.COM");
        // Non-ASCII bytes are left alone, and no trimming happens.
        assert_eq!(url("HTTP Ü", "h", 80, "/").scheme(), "http ü");
    }

    #[test]
    fn clamps_out_of_range_ports_to_the_sentinel() {
        for port in [-2, -1, 65536, 70000, i32::MAX, i32::MIN] {
            assert_eq!(url("http", "host", port, "/").port(), NO_PORT);
        }
        for port in [0, 1, 80, 65535] {
            assert_eq!(url("http", "host", port, "/").port(), port);
        }
    }

    #[test]
    fn omits_the_port_only_when_absent() {
        assert_eq!(url("http", "host", -1, "/").to_string(), "http://host/");
        // Port zero is in range, so it is kept and rendered.
        assert_eq!(url("http", "host", 0, "/").to_string(), "http://host:0/");
    }

    #[test]
    fn prepends_a_slash_to_a_relative_path() {
        assert_eq!(url("http", "host", 80, "noslash").path(), "/noslash");
        assert_eq!(url("http", "host", 80, "a/b").path(), "/a/b");
        // Already rooted, or empty: left exactly as given.
        assert_eq!(url("http", "host", 80, "//x").path(), "//x");
        assert_eq!(url("http", "host", 80, "").path(), "");
    }

    #[test]
    fn drops_the_authority_without_a_scheme() {
        assert_eq!(url("", "example.com", 80, "/").to_string(), "/");
        // An empty host still gets its separators when a scheme is present.
        assert_eq!(url("http", "", 80, "/").to_string(), "http://:80/");
    }

    #[test]
    fn query_and_fragment_are_passed_through_verbatim() {
        let u = URL::from_components("http", "h", 80, "/", "?q=1", "#f");
        assert_eq!(u.to_string(), "http://h:80/??q=1##f");
    }

    #[test]
    fn validity_needs_a_host_or_a_path() {
        assert!(!URL::from_components("", "", 80, "", "", "").is_valid());
        // A scheme, query, or fragment on its own is not enough.
        assert!(!URL::from_components("sc", "", 80, "", "qq", "ff").is_valid());
        assert!(URL::from_components("", "", 80, "/pp", "", "").is_valid());
        assert!(URL::from_components("", "hh", 80, "", "", "").is_valid());
    }
}

