    add(&["https", "www.google.com", "443", "/search", "q=test", "results"]);
    add(&["ftp", "ftp.example.org", "21", "/files/document.pdf", "", ""]);
    add(&["http", "localhost", "8080", "/api/v1/users", "id=123&name=john", "profile"]);
    add(&["https", "api.github.com", "443", "/repos/owner/repo", "page=1&per_page=100", ""]);

    // Wrong argument counts: the C++ main bails out with status 1.
    add(&[]);
    add(&["http"]);
    add(&["http", "h", "80"]);
    add(&["http", "h", "80", "/", ""]);
    add(&["http", "h", "80", "/", "", "", "extra", "more"]);

