        "abc", "", "-", "+", " ", "1 2", "000000000000000000000000000000000080", "- 80",
        "--80", "+-80", ".80", "1e3", "6553.5",
    ];
    for port in ports {
        add(&["http", "host", port, "/p", "q", "f"]);
    }

    let fixed = cases.len();

    // Randomized fuzzing over the same shape.
    let mut rng = Rng(0x2026_0808_DEAD_BEEF);
    let alphabet: Vec<char> = "abzAZ09/:?#&=. -_%\t~[]üÄ€".chars().collect();
    const FUZZ: usize = 5000;
    for _ in 0..FUZZ {
        let mut blob = |rng: &mut Rng| -> String {
            let len = rng.below(9);
            (0..len).map(|_| *rng.pick(&alphabet)).collect()
        };
        let (scheme, host) = (blob(&mut rng), blob(&mut rng));
