    for (args, want, got) in failures.iter().take(10) {
        println!("  args={args:?}");
        println!("    cpp ={:?}", render(want));
        println!("    rust={:?}", render(got));
    }
    std::process::exit(1);
}

fn render((code, stdout, stderr): &Result) -> (Option<i32>, String, String) {
    (
        *code,
        String::from_utf8_lossy(stdout).into_owned(),
        String::from_utf8_lossy(stderr).into_owned(),
    )
}

